mapper.select:
SELECT CAST(cl.clean_log_id AS CHAR) AS id, DATE_FORMAT(cl.created_at, '%Y-%m-%d %H:%i:%s') AS operatorTime, COALESCE(cs.name, CAST(cl.operator_id AS CHAR), '-') AS operatorName, CASE cl.action_type WHEN 'create' THEN '创建保洁' WHEN 'notify' THEN '通知保洁' WHEN 'assign' THEN '分配保洁' WHEN 'start' THEN '开始保洁' WHEN 'complete' THEN '完成保洁' WHEN 'cancel' THEN '取消保洁' WHEN 'checkout_auto_create' THEN '退房自动派单' ELSE cl.action_type END AS operatorTypeName, COALESCE(cl.action_detail, '') AS operatorDetails, rc.name AS roomType, r.room_name AS roomName FROM clean_log cl LEFT JOIN clean_staff cs ON cs.clean_staff_id = cl.clean_staff_id AND cs.camp_id = cl.camp_id AND cs.is_deleted = 0 LEFT JOIN room r ON r.room_id = cl.room_id AND r.camp_id = cl.camp_id AND r.is_deleted = 0 AND r.status = 1 LEFT JOIN room_category rc ON rc.room_category_id = cl.room_category_id AND rc.camp_id = cl.camp_id AND rc.is_deleted = 0 AND rc.status = 1 WHERE cl.camp_id = #{campId}
AND cl.poi_id = #{poiId}
AND cl.room_id IN
#{roomId}
AND (cl.clean_staff_id = #{operatorId} OR cl.operator_id = #{operatorId})
AND cl.created_at >= #{operatorStartTime}
AND cl.created_at < #{operatorEndExclusiveTime}
ORDER BY cl.created_at DESC, cl.clean_log_id DESC
